def rle(s):
    if not s:
        return ""
    result = []
    count = 1
    for char in s[1:]:
        if char == s[0]:
            count += 1
        else:
            result.append(f"{s[0]}{count}")
            count = 1
    result.append(f"{s[0]}{count}")
    return "".join(result)

def to_roman(n):
    if not (1 <= n <= 3999):
        raise ValueError("Input must be between 1 and 3999")

    val_to_sym = [
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")
    ]

    result = []
    for value, symbol in val_to_sym:
        while n >= value:
            n -= value
            result.append(symbol)
    return "".join(result)

def balanced(s):
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    opens = set('([{')
    for char in s:
        if char in opens:
            stack.append(char)
        elif char in pairs:
            if not stack or stack[-1] != pairs[char]:
                return False
            stack.pop()
    return not stack

def merge(a, b):
    result = []
    i, j = 0, 0
    # Compare elements from both lists, appending the smaller one
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            result.append(a[i])
            i += 1
        else:
            result.append(b[j])
            j += 1
    # Append any remaining elements from either list
    while i < len(a):
        result.append(a[i])
        i += 1
    while j < len(b):
        result.append(b[j])
        j += 1
    return result
